{
  "title": "数据迷宫",
  "scene": "你站在一座高耸入云的赛博朋克大楼前，大楼外墙闪耀着霓虹灯的光芒。入口处的屏幕上显示着：欢迎来到兆光科技，数据即是力量。突然，一位身穿黑色风衣、戴着义体眼睛的男子走过来，低声说道：‘如果你需要进入，我这里有一份数据破解程序，但需要1000元信用点。’不远处，一位正在调试设备的保安注意到了你们，他似乎对义体眼睛男子的行为不太满意，但没有采取行动。你可以尝试多种方法进入大楼。",
  "goal": "找到进入大楼的方法",
  "clue": "保安的反应暗示义体眼睛男子可能不可信",
  "choices": [
    {
      "id": "A",
      "text": "购买破解程序",
      "outcome": "你支付了1000元信用点，但当你尝试使用程序时，它根本无法破解大楼的安全系统。保安走了过来，怀疑你是骗子的同伙，但没有进一步行动。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "观察保安",
      "outcome": "你注意到保安在调试一个类似门禁系统的设备。趁他不注意，你悄悄地记录下了他输入的代码。使用这个代码，你成功进入了大楼。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "寻找其他入口",
      "outcome": "你绕着大楼走了一圈，发现了一个备用入口。虽然入口的保安更加严格，但你成功说服了他，进入了大楼。",
      "result": "partial",
      "next": "next_level"
    }
  ]
}
